    "data": "setBpm(96);\nsetMasterVolume(1.0);\n\nconst wubFx = await livePrepare(\"wobble-kick-bass-sample-fx\", async ({ fx, sample }) => {\n  await sample.load(\n    \"sonic-pi/drum-heavy-kick\"\n  );\n  await sample.load(\n    \"sonic-pi/bass-hit-c\"\n  );\n\n  const wobble = fx.wobble({\n    cutoff: 900,\n    depth: 1600,\n    rate: 0.5,\n    resonance: 6,\n    mix: 0.65,\n  });\n  const delay = fx.delay({\n    time: 0.24,\n    feedback: 0.32,\n    mix: 0.18,\n  });\n  const reverb = fx.reverb({\n    mix: 0.1,\n    tone: 4200,\n  });\n\n  return {\n    wobble,\n    delay,\n    reverb,\n  };\n});\n\nfx.setChain([\n  wubFx.wobble,\n  wubFx.delay,\n  wubFx.reverb,\n]);\n\nliveLoop(\"wub\", async () => {\n  await sample.play(\"sonic-pi/drum-heavy-kick\", {\n    gain: 0.9,\n    fadeIn: 0.002,\n    fadeOut: 0.05,\n  });\n\n  await sample.play(\"sonic-pi/bass-hit-c\", {\n    playbackRate: 0.8,\n    gain: 0.4,\n    fadeIn: 0.002,\n    fadeOut: 0.08,\n  });\n\n  await sleep(1);\n});\n"
